#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev;
    long long capacity, cost;
};

struct MinCostFlow {
    int n;
    std::vector<std::vector<Edge>> g;
    std::vector<long long> dist;
    std::vector<int> parent, parentEdge;
    long long flow, cost;

    MinCostFlow(int n) : n(n), g(n), dist(n), parent(n), parentEdge(n) {}

    void addEdge(int u, int v, long long cap, long long c) {
        g[u].push_back({v, (int)g[v].size(), cap, c});
        g[v].push_back({u, (int)g[u].size() - 1, 0, -c});
    }

    std::pair<long long, long long> minCostMaxFlow(int s, int t) {
        long long totalFlow = 0, totalCost = 0;
        while (true) {
            std::fill(dist.begin(), dist.end(), LLONG_MAX);
            dist[s] = 0;
            std::priority_queue<std::pair<long long, int>,
                                std::vector<std::pair<long long, int>>,
                                std::greater<>> pq;
            pq.emplace(0, s);
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dist[u]) continue;
                for (int i = 0; i < (int)g[u].size(); ++i) {
                    auto &e = g[u][i];
                    if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost) {
                        dist[e.to] = dist[u] + e.cost;
                        parent[e.to] = u;
                        parentEdge[e.to] = i;
                        pq.emplace(dist[e.to], e.to);
                    }
                }
            }
            if (dist[t] == LLONG_MAX) break;
            long long pushFlow = LLONG_MAX;
            for (int u = t; u != s; u = parent[u]) {
                pushFlow = std::min(pushFlow, g[parent[u]][parentEdge[u]].capacity);
            }
            for (int u = t; u != s; u = parent[u]) {
                auto &e = g[parent[u]][parentEdge[u]];
                e.capacity -= pushFlow;
                g[u][e.rev].capacity += pushFlow;
                totalCost += pushFlow * e.cost;
            }
            totalFlow += pushFlow;
        }
        return {totalFlow, totalCost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    std::istringstream iss(line);
    int n;
    string s;
    iss >> n >> s;
    std::vector<int> a(n);
    std::vector<int> cnt(26, 0);
    std::string nums_line;
    getline(cin, nums_line);
    std::istringstream iss_nums(nums_line);
    for (int i = 0; i < n; ++i) {
        iss_nums >> a[i];
        cnt[s[i] - 'a']++;
    }
    int g_size = n + 100;
    int source = n + 98;
    int target = source + 1;
    MinCostFlow g(g_size);
    for (int i = 0; i * 2 < n; ++i) {
        g.addEdge(i, target, 2, 0);
    }
    for (int i = 0; i < 26; ++i) {
        g.addEdge(source, n + i, cnt[i], 0);
        for (int j = 0; j * 2 < n; ++j) {
            if (s[j] == s[n - j - 1]) {
                int w = 0;
                if (s[j] - 'a' == i) w = -std::max(a[j], a[n - j - 1]);
                g.addEdge(n + i, j, 1, w);
            } else {
                int w = 0;
                if (s[j] - 'a' == i) w -= a[j];
                if (s[n - j - 1] - 'a' == i) w -= a[n - j - 1];
                g.addEdge(n + i, j, 1, w);
            }
        }
    }
    auto [flow, cost] = g.minCostMaxFlow(source, target);
    std::cout << -cost << "\n";
    return 0;
}

